/**
 * Push to Asana — CLI Script
 * 
 * Reads the PAT from .env.local and a project JSON file,
 * then creates the full Asana project (sections, tasks, milestones).
 * 
 * Usage:
 *   node scripts/push-to-asana.js [path-to-json]
 * 
 * If no path is given, looks for the most recent .json file in scripts/exports/
 * 
 * The JSON file is generated by the cx-dashboard "Export to Asana" button.
 */

const fs = require('fs')
const path = require('path')

// ─── Load PAT from .env.local ──────────────────────────────────────────────────
function loadEnv() {
  const envPath = path.resolve(__dirname, '..', '.env.local')
  if (!fs.existsSync(envPath)) {
    console.error('❌ .env.local not found at:', envPath)
    console.error('   Create it with: ASANA_PAT=your_token_here')
    process.exit(1)
  }
  const lines = fs.readFileSync(envPath, 'utf-8').split('\n')
  const env = {}
  for (const line of lines) {
    const trimmed = line.trim()
    if (!trimmed || trimmed.startsWith('#')) continue
    const eqIdx = trimmed.indexOf('=')
    if (eqIdx > 0) {
      env[trimmed.slice(0, eqIdx)] = trimmed.slice(eqIdx + 1)
    }
  }
  return env
}

const env = loadEnv()
const PAT = env.ASANA_PAT

if (!PAT) {
  console.error('❌ ASANA_PAT not found in .env.local')
  console.error('   Add this line: ASANA_PAT=2/1234.../abcdef...')
  process.exit(1)
}

// ─── Asana API Helpers ──────────────────────────────────────────────────────────
const API_BASE = 'https://app.asana.com/api/1.0'

async function apiCall(method, urlPath, body = null) {
  const opts = {
    method,
    headers: {
      'Authorization': `Bearer ${PAT}`,
      'Content-Type': 'application/json',
    },
  }
  if (body) opts.body = JSON.stringify({ data: body })

  const resp = await fetch(`${API_BASE}${urlPath}`, opts)
  if (!resp.ok) {
    const err = await resp.text()
    throw new Error(`Asana API error (${resp.status}): ${err}`)
  }
  const json = await resp.json()
  return json.data
}

async function getWorkspaces() { return apiCall('GET', '/workspaces') }
async function getMe() { return apiCall('GET', '/users/me') }

async function createProject(workspaceGid, name, notes, color = 'light-orange') {
  return apiCall('POST', '/projects', { workspace: workspaceGid, name, notes, color, default_view: 'timeline' })
}

async function createSection(projectGid, name) {
  return apiCall('POST', `/projects/${projectGid}/sections`, { name })
}

async function createTask(projectGid, sectionGid, taskData) {
  const data = {
    projects: [projectGid],
    memberships: [{ project: projectGid, section: sectionGid }],
    name: taskData.name,
    notes: taskData.notes || '',
  }
  if (taskData.start_on) data.start_on = taskData.start_on
  if (taskData.due_on) data.due_on = taskData.due_on
  if (taskData.resource_subtype) data.resource_subtype = taskData.resource_subtype
  return apiCall('POST', '/tasks', data)
}

async function setDependency(taskGid, dependsOnGid) {
  return apiCall('POST', `/tasks/${taskGid}/addDependencies`, { dependencies: [dependsOnGid] })
}

function sleep(ms) { return new Promise(r => setTimeout(r, ms)) }

// ─── Date helpers ───────────────────────────────────────────────────────────────
function formatDate(date) { return date.toISOString().split('T')[0] }
function addDays(date, days) { const d = new Date(date); d.setDate(d.getDate() + days); return d }

function getDuration(testCount) {
  if (testCount <= 3) return 1
  if (testCount <= 8) return 2
  if (testCount <= 15) return 3
  if (testCount <= 25) return 4
  return 5
}

// ─── Level labels ───────────────────────────────────────────────────────────────
const LEVEL_LABELS = {
  L1: 'L1 - Factory Testing', L2: 'L2 - Pre-SAT',
  L3: 'L3 - SAT', L4: 'L4 - FPT', L5: 'L5 - Energization',
}

function buildTestChecklist(tests, equipName) {
  const lines = []
  lines.push(`━━━ TESTS (${tests.length}) ━━━\n`)
  const byLevel = {}
  for (const [level, name] of tests) {
    if (!byLevel[level]) byLevel[level] = []
    byLevel[level].push(name)
  }
  for (const level of ['L1', 'L2', 'L3', 'L4', 'L5']) {
    if (!byLevel[level]) continue
    lines.push(`${LEVEL_LABELS[level] || level}:`)
    for (const name of byLevel[level]) lines.push(`☐ ${name}`)
    lines.push('')
  }
  lines.push(`━━━ INFO ━━━`)
  lines.push(`Equipment: ${equipName}`)
  lines.push(`Total tests: ${tests.length}`)
  return lines.join('\n')
}

// ─── Main ───────────────────────────────────────────────────────────────────────
async function main() {
  // Find the JSON file
  let jsonPath = process.argv[2]
  if (!jsonPath) {
    const exportsDir = path.resolve(__dirname, 'exports')
    if (!fs.existsSync(exportsDir)) {
      console.error('❌ No JSON file specified and scripts/exports/ does not exist')
      console.error('   Usage: node scripts/push-to-asana.js <path-to-json>')
      console.error('   Or export from the dashboard first (creates scripts/exports/*.json)')
      process.exit(1)
    }
    const files = fs.readdirSync(exportsDir)
      .filter(f => f.endsWith('.json'))
      .sort()
      .reverse()
    if (files.length === 0) {
      console.error('❌ No JSON files found in scripts/exports/')
      console.error('   Export from the dashboard first')
      process.exit(1)
    }
    jsonPath = path.join(exportsDir, files[0])
    console.log(`📁 Using latest export: ${files[0]}`)
  }

  if (!fs.existsSync(jsonPath)) {
    console.error(`❌ File not found: ${jsonPath}`)
    process.exit(1)
  }

  const projectData = JSON.parse(fs.readFileSync(jsonPath, 'utf-8'))
  const { projectName, equipment, sections } = projectData

  console.log(`\n🚀 Pushing to Asana: "${projectName}"`)
  console.log(`   Equipment items: ${equipment.length}`)
  console.log(`   Sections: ${Object.keys(sections).length}\n`)

  // 1. Verify connection
  console.log('🔑 Verifying PAT...')
  const me = await getMe()
  console.log(`   ✓ Authenticated as: ${me.name} (${me.email})`)

  // 2. Get workspace
  console.log('🏢 Finding workspace...')
  const workspaces = await getWorkspaces()
  if (!workspaces || workspaces.length === 0) throw new Error('No workspaces found')
  const workspace = workspaces[0]
  console.log(`   ✓ Workspace: ${workspace.name}`)

  // 3. Create project
  console.log('📋 Creating project...')
  const project = await createProject(
    workspace.gid,
    projectName,
    `HV/MV Substation Commissioning Project\nGenerated by Cx-Dashboard on ${new Date().toLocaleDateString()}\nEquipment items: ${equipment.length}`,
    'light-orange'
  )
  console.log(`   ✓ Project created: ${project.gid}`)
  await sleep(200)

  // 4. Create milestones
  console.log('🏁 Creating milestones...')
  const baseDate = new Date()
  baseDate.setDate(baseDate.getDate() + 1)

  const milestones = [
    { name: '🏁 Commissioning Kickoff', offset: 0 },
    { name: '📋 L2 Documentation Complete', offset: 14 },
    { name: '⚡ L3 SAT Complete', offset: 49 },
    { name: '🔗 L4 FPT Complete', offset: 63 },
    { name: '🟢 C2E — Ready for Energization', offset: 70 },
    { name: '⚡ ENERGIZATION', offset: 77 },
    { name: '✅ Declaration of Fitness', offset: 84 },
  ]

  const msSection = await createSection(project.gid, '🏁 Milestones')
  await sleep(200)

  const milestoneGids = []
  for (const ms of milestones) {
    const task = await createTask(project.gid, msSection.gid, {
      name: ms.name,
      due_on: formatDate(addDays(baseDate, ms.offset)),
      resource_subtype: 'milestone',
    })
    milestoneGids.push(task.gid)
    process.stdout.write('   .')
    await sleep(200)
  }
  console.log(' ✓')

  // 5. Chain milestone dependencies
  console.log('🔗 Setting dependencies...')
  for (let i = 1; i < milestoneGids.length; i++) {
    try {
      await setDependency(milestoneGids[i], milestoneGids[i - 1])
      await sleep(200)
    } catch (e) { /* non-critical */ }
  }
  console.log('   ✓')

  // 6. Create equipment sections + tasks
  const sectionNames = Object.keys(sections)
  console.log(`⚙️  Creating ${sectionNames.length} sections with tasks...`)
  let taskDayOffset = 0
  let totalTasks = 0

  for (let i = 0; i < sectionNames.length; i++) {
    const sName = sectionNames[i]
    const items = sections[sName]
    process.stdout.write(`   [${i + 1}/${sectionNames.length}] ${sName} (${items.length} items)`)

    const section = await createSection(project.gid, sName)
    await sleep(200)

    for (const item of items) {
      const tests = item.tests || []
      const duration = getDuration(tests.length)
      const startDate = formatDate(addDays(baseDate, taskDayOffset))
      const dueDate = formatDate(addDays(baseDate, taskDayOffset + duration))

      const notes = tests.length > 0
        ? buildTestChecklist(tests, item.name)
        : `Equipment: ${item.name}\nType: ${item.type}`

      await createTask(project.gid, section.gid, {
        name: item.name,
        notes,
        start_on: startDate,
        due_on: dueDate,
      })

      totalTasks++
      taskDayOffset += Math.max(1, duration - 1)
      await sleep(150)
    }

    taskDayOffset += 1
    console.log(' ✓')
  }

  // 7. Done!
  const projectUrl = `https://app.asana.com/0/${project.gid}`
  console.log(`\n${'═'.repeat(60)}`)
  console.log(`✅ SUCCESS!`)
  console.log(`   Project: ${projectName}`)
  console.log(`   Tasks: ${totalTasks}`)
  console.log(`   Sections: ${sectionNames.length}`)
  console.log(`   Milestones: ${milestones.length}`)
  console.log(`   URL: ${projectUrl}`)
  console.log(`${'═'.repeat(60)}\n`)

  // Open in browser (optional)
  const { exec } = require('child_process')
  exec(`start ${projectUrl}`)
}

main().catch(err => {
  console.error(`\n❌ Error: ${err.message}`)
  process.exit(1)
})
